-- Isolated schema. No existing NAZU tables are read, altered or migrated.
create schema nazu_cloud;
revoke all on schema nazu_cloud from public, anon, authenticated;
create table nazu_cloud.organizations(id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 2 and 80), created_at timestamptz not null default now());
create table nazu_cloud.organization_members(organization_id uuid not null references nazu_cloud.organizations on delete cascade,user_id uuid not null references auth.users on delete cascade,role text not null check(role in ('owner','admin','developer','readonly')),primary key(organization_id,user_id));
create index on nazu_cloud.organization_members(user_id);
create table nazu_cloud.projects(id uuid primary key default gen_random_uuid(), organization_id uuid not null references nazu_cloud.organizations on delete cascade,name text not null,origins text[] not null default '{}',created_at timestamptz not null default now(),unique(id,organization_id));
create table nazu_cloud.api_keys(id uuid primary key default gen_random_uuid(),organization_id uuid not null,project_id uuid not null,prefix text not null,secret_hash text not null unique check(length(secret_hash)=64),scopes text[] not null,expires_at timestamptz,revoked_at timestamptz,created_at timestamptz not null default now(),foreign key(project_id,organization_id) references nazu_cloud.projects(id,organization_id) on delete cascade);
create table nazu_cloud.wallet_challenges(id uuid primary key default gen_random_uuid(),organization_id uuid not null,project_id uuid not null,address text not null,chain_id bigint not null,origin text not null,message text not null,nonce text not null unique,issued_at timestamptz not null,expires_at timestamptz not null,used_at timestamptz,foreign key(project_id,organization_id) references nazu_cloud.projects(id,organization_id) on delete cascade);
create table nazu_cloud.wallet_sessions(id uuid primary key default gen_random_uuid(),organization_id uuid not null,project_id uuid not null,address text not null,origin text not null,token_hash text not null unique,expires_at timestamptz not null,revoked_at timestamptz,created_at timestamptz not null default now(),foreign key(project_id,organization_id) references nazu_cloud.projects(id,organization_id) on delete cascade);
create table nazu_cloud.rpc_monitors(id uuid primary key default gen_random_uuid(),organization_id uuid not null,project_id uuid not null,name text not null,endpoint text not null check(endpoint like 'https://%'),chain_id bigint not null check(chain_id>0),interval_seconds int not null default 300 check(interval_seconds between 300 and 86400),latency_threshold_ms int not null default 2000 check(latency_threshold_ms between 100 and 30000),status text not null default 'unknown' check(status in ('healthy','degraded','down','unknown','paused')),paused boolean not null default false,consecutive_failures int not null default 0,next_check_at timestamptz not null default now(),last_checked_at timestamptz,lease_owner uuid,lease_until timestamptz,created_at timestamptz not null default now(),unique(id,organization_id),foreign key(project_id,organization_id) references nazu_cloud.projects(id,organization_id) on delete cascade);
create index on nazu_cloud.rpc_monitors(next_check_at) where not paused;
create table nazu_cloud.monitor_checks(id bigint generated always as identity primary key,organization_id uuid not null,monitor_id uuid not null,scheduled_at timestamptz not null,checked_at timestamptz not null default now(),status text not null check(status in ('healthy','degraded','down','unknown')),latency_ms int check(latency_ms>=0),block_number numeric(78,0),error_code text,unique(monitor_id,scheduled_at),foreign key(monitor_id,organization_id) references nazu_cloud.rpc_monitors(id,organization_id) on delete cascade);
create index on nazu_cloud.monitor_checks(monitor_id,checked_at desc);
create table nazu_cloud.monitor_incidents(id uuid primary key default gen_random_uuid(),organization_id uuid not null,monitor_id uuid not null,opened_at timestamptz not null default now(),resolved_at timestamptz,foreign key(monitor_id,organization_id) references nazu_cloud.rpc_monitors(id,organization_id) on delete cascade,check(resolved_at is null or resolved_at>=opened_at));
create unique index one_open_incident on nazu_cloud.monitor_incidents(monitor_id) where resolved_at is null;
create table nazu_cloud.alert_channels(id uuid primary key default gen_random_uuid(),organization_id uuid not null references nazu_cloud.organizations on delete cascade,kind text not null check(kind in ('email','discord')),destination_ciphertext text not null,verified_at timestamptz,created_at timestamptz not null default now(),unique(id,organization_id));
create table nazu_cloud.alert_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null,monitor_id uuid not null,channel_id uuid not null,cooldown_seconds int not null default 900 check(cooldown_seconds>=300),foreign key(monitor_id,organization_id) references nazu_cloud.rpc_monitors(id,organization_id) on delete cascade,foreign key(channel_id,organization_id) references nazu_cloud.alert_channels(id,organization_id) on delete cascade);
create table nazu_cloud.alert_deliveries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references nazu_cloud.organizations on delete cascade,incident_id uuid references nazu_cloud.monitor_incidents on delete cascade,channel_id uuid not null,event text not null check(event in ('down','recovery','latency','test')),status text not null default 'pending' check(status in ('pending','sent','failed')),attempts int not null default 0,locked_until timestamptz,lease_owner uuid,next_attempt_at timestamptz not null default now(),delivered_at timestamptz,unique(incident_id,channel_id,event),foreign key(channel_id,organization_id) references nazu_cloud.alert_channels(id,organization_id) on delete cascade);
create table nazu_cloud.api_usage_events(id bigint generated always as identity primary key,organization_id uuid not null references nazu_cloud.organizations on delete cascade,project_id uuid references nazu_cloud.projects on delete cascade,api_key_id uuid references nazu_cloud.api_keys on delete set null,status_code int not null,created_at timestamptz not null default now());
create index on nazu_cloud.api_usage_events(organization_id,created_at);
create table nazu_cloud.api_usage_daily(organization_id uuid not null references nazu_cloud.organizations on delete cascade,day date not null,successful bigint not null default 0,failed bigint not null default 0,limited bigint not null default 0,primary key(organization_id,day));
create table nazu_cloud.billing_customers(organization_id uuid primary key references nazu_cloud.organizations on delete cascade,provider_id text not null unique);
create table nazu_cloud.subscriptions(organization_id uuid primary key references nazu_cloud.organizations on delete cascade,provider_id text unique,plan text not null default 'free' check(plan in ('free','starter','pro','business')),status text not null default 'inactive',current_period_end timestamptz);
create table nazu_cloud.audit_logs(id bigint generated always as identity primary key,organization_id uuid not null references nazu_cloud.organizations on delete cascade,actor_id uuid,action text not null,created_at timestamptz not null default now());
create index on nazu_cloud.audit_logs(organization_id,created_at desc);
create table nazu_cloud.worker_jobs(id uuid primary key default gen_random_uuid(),kind text not null,payload jsonb not null,attempts int not null default 0,run_at timestamptz not null default now(),locked_until timestamptz,completed_at timestamptz);
create table nazu_cloud.system_settings(key text primary key,value jsonb not null);
create table nazu_cloud.rate_limits(bucket uuid not null,window_start timestamptz not null,count int not null,primary key(bucket,window_start));
-- Defense in depth: schema deliberately NOT exposed through PostgREST. Browser roles have no grants.
-- All application access passes through server-side membership checks; direct browser access is denied.
do $$ declare t record; begin for t in select tablename from pg_tables where schemaname='nazu_cloud' loop execute format('alter table nazu_cloud.%I enable row level security',t.tablename); execute format('revoke all on nazu_cloud.%I from public, anon, authenticated',t.tablename); end loop; end $$;
revoke all on all sequences in schema nazu_cloud from public,anon,authenticated;
